### Python

```python
import sys

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    s = [0] * (n + 1)
    for i in range(1, n + 1):
        s[i] = int(next(it))

    # 预处理光羽数列，所有不超过 n-1 的项
    fib = [1, 1]
    while fib[-1] <= n - 1:
        fib.append(fib[-1] + fib[-2])

    # dp[i] 表示到达第 i 个平台的最大总能量
    INF_NEG = -10**18
    dp = [INF_NEG] * (n + 1)
    dp[1] = s[1]

    for i in range(2, n + 1):
        for val in fib:
            if val > i - 1:       # 无法从更远的距离跳过来
                break
            if dp[i - val] != INF_NEG:
                dp[i] = max(dp[i], dp[i - val] + s[i])

    print(dp[n])

if __name__ == "__main__":
    main()
```

