import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] s = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            s[i] = sc.nextLong();
        }

        // 预处理光羽数列（不超过 n-1 的项）
        List<Integer> fib = new ArrayList<>();
        fib.add(1);
        fib.add(1);
        while (fib.get(fib.size() - 1) <= n - 1) {
            int size = fib.size();
            fib.add(fib.get(size - 1) + fib.get(size - 2));
        }

        long NEG_INF = (long) -1e18;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, NEG_INF);
        dp[1] = s[1];

        for (int i = 2; i <= n; i++) {
            for (int val : fib) {
                if (val > i - 1) break;      // 跳跃距离过大
                if (dp[i - val] != NEG_INF) {
                    dp[i] = Math.max(dp[i], dp[i - val] + s[i]);
                }
            }
        }

        System.out.println(dp[n]);
    }
}
